from pathlib import Path
import re
p = Path('/home/ubuntu/onex-windows-rebuild/client/src/pages/Home.tsx')
s = p.read_text()
s = s.replace('const [domain, setDomain] = useState("ALL");', 'const [domain, setDomain] = useState("ALL");\n  const [expandedBranches, setExpandedBranches] = useState<Record<string, boolean>>({});\n  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});\n  const [selectedWindow, setSelectedWindow] = useState<any>(null);')
s = s.replace('const windows = trpc.windows.list.useQuery({ search: windowSearch || undefined, domain, limit: 80 });', 'const windows = trpc.windows.list.useQuery({ search: windowSearch || undefined, domain, limit: 80 });\n  const systemTree = trpc.windows.tree.useQuery();')
start = s.index('      {section === "windows" && <section className="window-explorer">')
end = s.index('      {section === "ar" && <section className="ar-workspace">', start)
new_block = '''      {section === "windows" && <section className="window-explorer"><div className="explorer-toolbar"><div><p className="panel-kicker">REAL LEGACY SYSTEM TREE</p><h2>شجرة النظام الفعلية</h2><p>فروع المجالات، مجموعات الـForms، وتفاصيل كل شاشة كما وردت في كتالوج Onyx الأصلي.</p></div><div className="catalog-count"><strong>1,490</strong><span>شاشة مفهرسة</span></div></div><div className="tree-toolbar"><div className="search-field"><Search size={16} /><Input placeholder="ابحث برقم الشاشة أو اسم الـForm أو المجال..." value={windowSearch} onChange={(e) => setWindowSearch(e.target.value)} /></div><div className="tree-legend"><span><i className="tree-dot built" />قيد البناء</span><span><i className="tree-dot indexed" />مفهرسة</span><span><i className="tree-dot spec" />مواصفة</span></div></div><div className="tree-layout"><div className="system-tree"><div className="tree-root"><Boxes size={16} /><div><b>ONEX / ERP</b><span>النظام الرئيسي · 12 مجالًا · 1,490 شاشة</span></div><span className="root-badge">ROOT</span></div>{(systemTree.data ?? []).filter((branch: any) => domain === "ALL" || branch.domain === domain || branch.domain.startsWith(domain + "/")).map((branch: any) => { const branchOpen = expandedBranches[branch.id] ?? branch.id.includes("AR"); return <div className="tree-branch" key={branch.id}><button className="tree-branch-row" onClick={() => setExpandedBranches((prev) => ({ ...prev, [branch.id]: !branchOpen }))}><span className={`chevron ${branchOpen ? "open" : ""}`}>‹</span><span className="branch-icon"><Boxes size={15} /></span><span className="branch-label"><b>{branch.label}</b><small>{branch.domain}</small></span><strong>{branch.windows}</strong></button>{branchOpen && <div className="tree-children">{branch.groups.map((group: any) => { const groupOpen = expandedGroups[group.id] ?? (branch.id.includes("AR") && group.label === "ARST"); return <div className="tree-group" key={group.id}><button className="tree-group-row" onClick={() => setExpandedGroups((prev) => ({ ...prev, [group.id]: !groupOpen }))}><span className={`chevron ${groupOpen ? "open" : ""}`}>‹</span><span className="folder-icon"><Package size={13} /></span><span>{group.label}</span><em>{group.count}</em></button>{groupOpen && <div className="tree-windows">{group.windows.filter((win: any) => !windowSearch || `${win.screenNo} ${win.screenName} ${win.formName} ${win.capability}`.toLowerCase().includes(windowSearch.toLowerCase())).map((win: any) => <button key={win.legacyForm} className={`tree-window-row ${selectedWindow?.legacyForm === win.legacyForm ? "selected" : ""}`} onClick={() => setSelectedWindow(win)}><span className={`tree-status ${win.buildState === "قيد البناء" ? "building" : win.buildState === "متحقق" ? "verified" : win.buildState === "مواصفة" ? "spec" : "indexed"}`} /><span className="tree-window-name"><b>{win.screenName}</b><small>{win.formName}</small></span><span className="tree-screen-no">{win.screenNo}</span><ChevronLeft size={13} /></button>)}</div>}</div>})}</div>}</div>})}</div></div><div className="window-detail"><div className="detail-header"><div><p className="panel-kicker">SCREEN CONTRACT</p><h3>{selectedWindow?.screenName ?? "اختر شاشة من الشجرة"}</h3><p>{selectedWindow?.formName ?? "تظهر هنا هوية الشاشة وعلاقاتها وصلاحياتها"}</p></div><StatusPill status={selectedWindow?.buildState ?? "مفهرسة"} /></div>{selectedWindow ? <><div className="detail-code">{selectedWindow.screenNo}<span>{selectedWindow.systemNo}</span></div><div className="detail-grid"><div><span>رقم الشاشة</span><b>{selectedWindow.screenNo}</b></div><div><span>اسم الشاشة</span><b>{selectedWindow.screenName}</b></div><div><span>الأب Parent</span><b>{selectedWindow.parentId}</b></div><div><span>رقم النظام</span><b>{selectedWindow.systemNo}</b></div><div><span>نوع العنصر</span><b>{selectedWindow.itemType}</b></div><div><span>اسم الـForm</span><b>{selectedWindow.formName}</b></div><div><span>ترتيب العرض</span><b>{selectedWindow.displayOrder}</b></div><div><span>حالة البناء</span><b>{selectedWindow.buildState}</b></div><div><span>صلاحية المستخدم</span><b>{selectedWindow.userPermission}</b></div><div><span>صلاحية الشركة أو الفرع</span><b>{selectedWindow.companyBranchPermission}</b></div></div><div className="detail-actions"><Button onClick={() => { setSection("ar"); toast.info(`تم فتح عقد ${selectedWindow.formName}`); }}><FileText size={15} />فتح عقد الشاشة</Button><Button variant="outline" onClick={() => toast.info("سيبدأ بناء منطق الشاشة بعد اعتماد مصدرها FMB/PLL")}>بدء البناء</Button></div></> : <div className="empty-detail"><PanelLeft size={28} /><p>اضغط على أي شاشة في الشجرة لعرض عقدها التفصيلي.</p></div>}</div></div></section>}\n'''
s = s[:start] + new_block + s[end:]
p.write_text(s)
print('patched tree UI')
